package com.appnexus.masterdata.product;
import com.appnexus.masterdata.MasterData;
import com.appnexus.platform.authorization.AccessAuthorization;
import com.appnexus.platform.tenant.VerifiedTenantContext;
import java.math.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
/** 规格、可选SKU和组合结构领域服务；父锁/CAS及追加历史同事务，不触及库存、定价或拆装。 */
@Service public final class ProductStructureService {
 private final JdbcTemplate jdbc;private final AccessAuthorization access;private final TransactionTemplate tx;private final ProductV1Service products;
 /** @param jdbc UTC数据源 @param access 公开授权端口 @param manager 同数据源事务 @param products 同领域快照/完整性/历史执行器 */
 public ProductStructureService(JdbcTemplate jdbc,AccessAuthorization access,PlatformTransactionManager manager,ProductV1Service products){this.jdbc=jdbc;this.access=access;this.tx=new TransactionTemplate(manager);this.products=products;}
 /** @param name 规格名称1至200字符 @param description 自定义描述最大2000字符 @param values 标准规格固定SPEC模板项值，标量或固定选项UUID @param version 商品当前CAS */
 public record Specification(String name,String description,List<SpecValue> values,Long version){}
 /** @param templateItemId 固定SPEC项UUID @param value INTEGER/DECIMAL/BOOLEAN标量或单选option UUID */
 public record SpecValue(String templateItemId,String value){}
 /** @param specificationId 已保存当前有效规格UUID @param code SKU独立编码，创建后不可修改 @param version 商品CAS */
 public record Sku(String specificationId,String code,Long version){}
 /** @param componentId 组成商品UUID @param quantity 组成商品基础单位下正数精确数量 @param componentVersion 当前组成商品版本 @param version 组合父商品CAS */
 public record Component(String componentId,String quantity,Long componentVersion,Long version){}
 /** @param enabled 目标启停状态 @param rowVersion 子记录当前CAS @param version 父商品CAS */
 public record State(Boolean enabled,Long rowVersion,Long version){}
 /** 查询规格/SKU/组成，effective按商品与规格分层状态计算，不把SKU.enabled当可用事实。 */
 public Object read(VerifiedTenantContext c,String id){require(c,"read");var p=parent(c,id,false,null);var out=new LinkedHashMap<String,Object>();out.put("mode",p.get("specification_mode"));out.put("form",p.get("product_form"));out.put("version",p.get("version"));out.put("specifications",jdbc.queryForList("SELECT BIN_TO_UUID(s.id) id,s.name,s.description,s.mode,s.enabled,s.version,s.retired_at retiredAt,(s.enabled AND s.retired_at IS NULL AND p.status='ENABLED') effective FROM md_product_specification s JOIN md_product_v1 p ON p.tenant_id=s.tenant_id AND p.id=s.product_id WHERE s.tenant_id=UUID_TO_BIN(?) AND s.product_id=UUID_TO_BIN(?) ORDER BY s.created_at,s.id",tenant(c),id));out.put("skus",jdbc.queryForList("SELECT BIN_TO_UUID(k.id) id,BIN_TO_UUID(k.specification_id) specificationId,k.code,k.enabled,k.version,(k.enabled AND s.enabled AND s.retired_at IS NULL AND p.status='ENABLED') effective FROM md_product_sku k JOIN md_product_specification s ON s.tenant_id=k.tenant_id AND s.id=k.specification_id JOIN md_product_v1 p ON p.tenant_id=k.tenant_id AND p.id=k.product_id WHERE k.tenant_id=UUID_TO_BIN(?) AND k.product_id=UUID_TO_BIN(?) ORDER BY k.code",tenant(c),id));out.put("components",jdbc.queryForList("SELECT BIN_TO_UUID(c.id) id,BIN_TO_UUID(c.component_product_id) componentId,p.code,p.name,CAST(c.quantity AS CHAR) quantity,c.component_version componentVersion,c.enabled,c.version,(c.enabled AND p.status='ENABLED' AND p.version=c.component_version AND EXISTS(SELECT 1 FROM md_product_v1 owner WHERE owner.tenant_id=c.tenant_id AND owner.id=c.product_id AND owner.status='ENABLED')) effective FROM md_product_component c JOIN md_product_v1 p ON p.tenant_id=c.tenant_id AND p.id=c.component_product_id WHERE c.tenant_id=UUID_TO_BIN(?) AND c.product_id=UUID_TO_BIN(?) ORDER BY p.code",tenant(c),id));attachAudit(c,out,"specifications","md_product_specification");attachAudit(c,out,"skus","md_product_sku");attachAudit(c,out,"components","md_product_component");return out;}
 /** 标准规格组合值按模板稳定顺序规范化；哈希仅用于唯一索引，碰撞仍拒绝并保留原串。 */
 public Object createSpecification(VerifiedTenantContext c,String product,Specification i){require(c,"manage_structure");if(i==null||i.version()==null||i.name()==null||i.name().isBlank()||i.name().length()>200||i.description()!=null&&i.description().length()>2000)throw invalid();return write(()->{var p=parent(c,product,true,i.version());String mode=(String)p.get("specification_mode"),config=(String)p.get("configId");if(!Set.of("STANDARD","CUSTOM").contains(mode)||config==null)throw invalid();var before=products.extensionSnapshot(c,product);var values=i.values()==null?List.<SpecValue>of():i.values();if(values.size()>200)throw invalid();var prepared=new ArrayList<Object[]>();var canonical=new StringBuilder();
 if(mode.equals("CUSTOM")){if(!values.isEmpty()||i.description()==null||i.description().isBlank())throw invalid();}
 else {var definitions=jdbc.queryForList("SELECT BIN_TO_UUID(ci.template_item_id) item,BIN_TO_UUID(ci.attribute_revision_id) revision,ci.data_type type,r.numeric_scale scale,CAST(r.validation_json AS CHAR) rules FROM md_product_category_config_item ci JOIN md_product_attribute_revision r ON r.tenant_id=ci.tenant_id AND r.id=ci.attribute_revision_id WHERE ci.tenant_id=UUID_TO_BIN(?) AND ci.config_id=UUID_TO_BIN(?) AND ci.purpose='SPEC' ORDER BY ci.attribute_id",tenant(c),config);if(definitions.isEmpty()||definitions.size()!=values.size())throw invalid();var supplied=new HashMap<String,String>();for(var v:values){if(v==null||v.value()==null||supplied.put(v.templateItemId(),v.value())!=null)throw invalid();}
 for(var d:definitions){String item=(String)d.get("item"),revision=(String)d.get("revision"),type=(String)d.get("type"),raw=supplied.get(item),normal=raw;Object integer=null,decimal=null,bool=null,option=null;if(raw==null)throw invalid();try{switch(type){case "INTEGER"->{if(!raw.matches("-?(0|[1-9][0-9]*)"))throw invalid();integer=Long.parseLong(raw);normal=integer.toString();}case "DECIMAL"->{if(!raw.matches("-?[0-9]+([.][0-9]+)?"))throw invalid();var n=new BigDecimal(raw);if(n.scale()>((Number)d.get("scale")).intValue()||n.precision()-n.scale()>18)throw invalid();decimal=n;normal=n.stripTrailingZeros().toPlainString();}case "BOOLEAN"->{if(!Set.of("true","false").contains(raw))throw invalid();bool=Boolean.parseBoolean(raw);}case "SINGLE_SELECT"->{uuid(raw);var opts=jdbc.queryForList("SELECT option_code FROM md_product_attribute_option WHERE tenant_id=UUID_TO_BIN(?) AND revision_id=UUID_TO_BIN(?) AND id=UUID_TO_BIN(?) AND enabled=TRUE",tenant(c),revision,raw);if(opts.size()!=1)throw invalid();option=raw;normal=(String)opts.getFirst().get("option_code");}default->throw invalid();}}catch(NumberFormatException e){throw invalid();}ProductAttributeRules.value(type,(String)d.get("rules"),Set.of("INTEGER","DECIMAL","BOOLEAN").contains(type)?raw:null,type.equals("SINGLE_SELECT")?1:0);canonical.append(item).append(':').append(revision).append(':').append(type).append(':').append(normal.length()).append(':').append(normal).append(';');prepared.add(new Object[]{item,revision,type,integer,decimal,bool,option});}}
 String id=UUID.randomUUID().toString(),signature=mode.equals("STANDARD")?canonical.toString():null;byte[] hash=null;if(signature!=null)try{hash=java.security.MessageDigest.getInstance("SHA-256").digest(signature.getBytes(StandardCharsets.UTF_8));}catch(java.security.NoSuchAlgorithmException e){throw new IllegalStateException(e);}jdbc.update("INSERT INTO md_product_specification(id,tenant_id,product_id,config_id,mode,name,description,combination_canonical,combination_hash,created_by,updated_by) VALUES(UUID_TO_BIN(?),UUID_TO_BIN(?),UUID_TO_BIN(?),UUID_TO_BIN(?),?,?,?,?,?,UUID_TO_BIN(?),UUID_TO_BIN(?))",id,tenant(c),product,config,mode,i.name().trim(),i.description(),signature,hash,actor(c),actor(c));for(var v:prepared)jdbc.update("INSERT INTO md_product_spec_value(id,tenant_id,specification_id,config_id,template_item_id,attribute_revision_id,value_type,integer_value,decimal_value,boolean_value,option_id,created_by,updated_by) VALUES(UUID_TO_BIN(?),UUID_TO_BIN(?),UUID_TO_BIN(?),UUID_TO_BIN(?),UUID_TO_BIN(?),UUID_TO_BIN(?),?,?,?,?,UUID_TO_BIN(?),UUID_TO_BIN(?),UUID_TO_BIN(?))",UUID.randomUUID().toString(),tenant(c),id,config,v[0],v[1],v[2],v[3],v[4],v[5],v[6],actor(c),actor(c));finish(c,product,i.version(),"SPEC_CREATE",before);return Map.of("id",id);});}
 /** 只有显式动作才创建SKU；父子归属复合外键兜底，SKU身份创建后不可修改。 */
 public Object createSku(VerifiedTenantContext c,String product,Sku i){require(c,"manage_structure");if(i==null||i.version()==null||i.code()==null||!i.code().matches("[A-Za-z0-9][A-Za-z0-9._-]{0,63}"))throw invalid();uuid(i.specificationId());return write(()->{parent(c,product,true,i.version());var before=products.extensionSnapshot(c,product);if(jdbc.queryForObject("SELECT COUNT(*) FROM md_product_specification WHERE tenant_id=UUID_TO_BIN(?) AND product_id=UUID_TO_BIN(?) AND id=UUID_TO_BIN(?) AND enabled=TRUE AND retired_at IS NULL",Integer.class,tenant(c),product,i.specificationId())!=1)throw invalid();String id=UUID.randomUUID().toString();jdbc.update("INSERT INTO md_product_sku(id,tenant_id,product_id,specification_id,code,created_by,updated_by) VALUES(UUID_TO_BIN(?),UUID_TO_BIN(?),UUID_TO_BIN(?),UUID_TO_BIN(?),?,UUID_TO_BIN(?),UUID_TO_BIN(?))",id,tenant(c),product,i.specificationId(),i.code(),actor(c),actor(c));finish(c,product,i.version(),"SKU_CREATE",before);return Map.of("id",id);});}
 /** 组合写入共用租户图锁，防止并发互加形成环；数量按组成基础单位精度，不自动换算。 */
 public Object addComponent(VerifiedTenantContext c,String product,Component i){require(c,"manage_structure");if(i==null||i.version()==null||i.componentVersion()==null||i.quantity()==null||!i.quantity().matches("(0|[1-9][0-9]{0,17})([.][0-9]{1,12})?"))throw invalid();uuid(i.componentId());var quantity=new BigDecimal(i.quantity());if(quantity.signum()<=0||product.equals(i.componentId()))throw invalid();return write(()->{graphLock(c);var p=parent(c,product,true,i.version());if(!"COMPOSITE".equals(p.get("product_form")))throw invalid();var before=products.extensionSnapshot(c,product);var child=parent(c,i.componentId(),false,null);if(!"ENABLED".equals(child.get("status"))||!i.componentVersion().equals(((Number)child.get("version")).longValue())||child.get("unitId")==null)throw invalid();Integer scale=jdbc.queryForObject("SELECT precision_scale FROM md_product_unit WHERE tenant_id=UUID_TO_BIN(?) AND id=UUID_TO_BIN(?) AND enabled=TRUE",Integer.class,tenant(c),child.get("unitId"));if(scale==null||quantity.scale()>scale)throw invalid();var seen=new HashSet<String>();var queue=new ArrayDeque<String>();queue.add(i.componentId());while(!queue.isEmpty()){String node=queue.remove();if(node.equals(product)||seen.size()>10000)throw invalid();if(!seen.add(node))continue;queue.addAll(jdbc.queryForList("SELECT BIN_TO_UUID(component_product_id) FROM md_product_component WHERE tenant_id=UUID_TO_BIN(?) AND product_id=UUID_TO_BIN(?) AND enabled=TRUE",String.class,tenant(c),node));}var existing=jdbc.queryForList("SELECT BIN_TO_UUID(id) id,enabled FROM md_product_component WHERE tenant_id=UUID_TO_BIN(?) AND product_id=UUID_TO_BIN(?) AND component_product_id=UUID_TO_BIN(?) FOR UPDATE",tenant(c),product,i.componentId());if(!existing.isEmpty()){if(Boolean.TRUE.equals(existing.getFirst().get("enabled")))throw invalid();String reused=(String)existing.getFirst().get("id");jdbc.update("UPDATE md_product_component SET quantity=?,component_version=?,enabled=TRUE,version=version+1,updated_by=UUID_TO_BIN(?),updated_at=CURRENT_TIMESTAMP(6) WHERE tenant_id=UUID_TO_BIN(?) AND id=UUID_TO_BIN(?)",quantity,i.componentVersion(),actor(c),tenant(c),reused);finish(c,product,i.version(),"COMPONENT_REPLACE",before);return Map.of("id",reused);}String id=UUID.randomUUID().toString();jdbc.update("INSERT INTO md_product_component(id,tenant_id,product_id,component_product_id,quantity,component_version,created_by,updated_by) VALUES(UUID_TO_BIN(?),UUID_TO_BIN(?),UUID_TO_BIN(?),UUID_TO_BIN(?),?,?,UUID_TO_BIN(?),UUID_TO_BIN(?))",id,tenant(c),product,i.componentId(),quantity,i.componentVersion(),actor(c),actor(c));finish(c,product,i.version(),"COMPONENT_ADD",before);return Map.of("id",id);});}
 /** 子对象启停按父CAS与子CAS原子修改；不能恢复退役规格，不能跨商品操作SKU。 */
 public Object state(VerifiedTenantContext c,String product,String kind,String id,State i){require(c,"manage_structure");uuid(id);if(i==null||i.version()==null||i.rowVersion()==null||i.enabled()==null)throw invalid();String table=switch(kind){case "specification"->"md_product_specification";case "sku"->"md_product_sku";case "component"->"md_product_component";default->throw invalid();};return write(()->{if(kind.equals("component"))graphLock(c);parent(c,product,true,i.version());if(kind.equals("component")&&i.enabled())throw invalid();var before=products.extensionSnapshot(c,product);int n=jdbc.update("UPDATE "+table+" SET enabled=?,version=version+1,updated_by=UUID_TO_BIN(?),updated_at=CURRENT_TIMESTAMP(6) WHERE tenant_id=UUID_TO_BIN(?) AND product_id=UUID_TO_BIN(?) AND id=UUID_TO_BIN(?) AND version=? AND enabled<>?"+(kind.equals("specification")?" AND retired_at IS NULL":""),i.enabled(),actor(c),tenant(c),product,id,i.rowVersion(),i.enabled());if(n!=1)throw changed();finish(c,product,i.version(),"STRUCTURE_STATE",before);return Map.of("ok",true);});}
 /** 已授权父商品内批量投影四审计，不接受外部表名，查询使用可信租户与已返回行ID。 */
 @SuppressWarnings("unchecked") private void attachAudit(VerifiedTenantContext c,Map<String,Object> output,String key,String table){if(!Set.of("md_product_specification","md_product_sku","md_product_component").contains(table))throw new IllegalArgumentException();for(var row:(List<Map<String,Object>>)output.get(key)){var audit=jdbc.query("SELECT BIN_TO_UUID(created_by) creator,created_at,BIN_TO_UUID(updated_by) updater,updated_at FROM "+table+" WHERE tenant_id=UUID_TO_BIN(?) AND id=UUID_TO_BIN(?)",(rs,n)->{var a=new LinkedHashMap<String,Object>();a.put("createdBy",rs.getString("creator"));a.put("updatedBy",rs.getString("updater"));a.put("createdAt",rs.getTimestamp("created_at")==null?null:rs.getTimestamp("created_at").toInstant().toString());a.put("updatedAt",rs.getTimestamp("updated_at")==null?null:rs.getTimestamp("updated_at").toInstant().toString());return a;},tenant(c),row.get("id"));if(!audit.isEmpty())row.put("audit",audit.getFirst());}}
 private void graphLock(VerifiedTenantContext c){jdbc.update("INSERT INTO md_product_category_guard(tenant_id,created_by,updated_by) VALUES(UUID_TO_BIN(?),UUID_TO_BIN(?),UUID_TO_BIN(?)) ON DUPLICATE KEY UPDATE tenant_id=tenant_id",tenant(c),actor(c),actor(c));jdbc.queryForList("SELECT tenant_id FROM md_product_category_guard WHERE tenant_id=UUID_TO_BIN(?) FOR UPDATE",tenant(c));}
 private Map<String,Object> parent(VerifiedTenantContext c,String id,boolean lock,Long version){uuid(id);var rows=jdbc.queryForList("SELECT product_form,specification_mode,BIN_TO_UUID(category_config_id) configId,BIN_TO_UUID(base_unit_id) unitId,status,draft_archived_at archived,structure_state structure,version FROM md_product_v1 WHERE tenant_id=UUID_TO_BIN(?) AND id=UUID_TO_BIN(?)"+(lock?" FOR UPDATE":""),tenant(c),id);if(rows.size()!=1)throw changed();var p=rows.getFirst();if(lock)products.ensureNotInApproval(c,id);if(lock&&(version==null||version<0||((Number)p.get("version")).longValue()!=version||"ENABLED".equals(p.get("status"))||p.get("archived")!=null||"LEGACY_PENDING".equals(p.get("structure"))))throw changed();return p;}
 private void finish(VerifiedTenantContext c,String id,long version,String event,Map<String,Object> before){if(jdbc.update("UPDATE md_product_v1 SET version=version+1,updated_by=UUID_TO_BIN(?),updated_at=CURRENT_TIMESTAMP(6) WHERE tenant_id=UUID_TO_BIN(?) AND id=UUID_TO_BIN(?) AND version=?",actor(c),tenant(c),id,version)!=1)throw changed();products.extensionEvent(c,id,event,before);}
 private void require(VerifiedTenantContext c,String action){if(c==null||!access.hasPermission(AccessAuthorization.Subject.tenant(c.accountId(),c.tenantId(),c.memberId()),"masterdata.product:"+action))throw new MasterData.Rejection(403,"MASTER_DATA_DENIED");}
 private <T>T write(java.util.function.Supplier<T> action){try{return tx.execute(s->action.get());}catch(org.springframework.dao.DataIntegrityViolationException e){throw new MasterData.Rejection(409,"PRODUCT_STRUCTURE_CONFLICT");}}
 private static void uuid(String id){try{if(!UUID.fromString(id).toString().equals(id))throw invalid();}catch(IllegalArgumentException|NullPointerException e){throw invalid();}}
 private static String tenant(VerifiedTenantContext c){return c.tenantId().toString();}private static String actor(VerifiedTenantContext c){return c.accountId().toString();}
 private static MasterData.Rejection invalid(){return new MasterData.Rejection(400,"PRODUCT_STRUCTURE_INVALID");}private static MasterData.Rejection changed(){return new MasterData.Rejection(409,"MASTER_DATA_CHANGED");}
}
